import type { Vec3 } from '../contracts/math';
import { clamp } from '../physics/helpers';
import type { BallObstacle, BallSample, ObstacleConfigBase, ObstacleEffect, ObstacleStepContext } from './types';
import { dotVec3, normalizeVec3, scaleVec3 } from './vec';
import type { ZoneShape } from './zones';
import { zoneContains, zoneFalloff } from './zones';

export type FanFalloff = 'none' | 'linear';

/** Fans can cycle on and off so a hole gets a rhythm instead of a constant push. */
export interface FanPulse {
  periodSeconds: number;
  /** share of the period the fan is blowing, 0..1 */
  dutyCycle?: number;
  /** phase offset in seconds */
  phase?: number;
}

export interface FanConfig extends ObstacleConfigBase {
  kind: 'fan';
  zone: ZoneShape;
  /** blow direction, normalized on construction */
  direction: Vec3;
  /** acceleration at full power, m/s^2 */
  strength: number;
  falloff?: FanFalloff;
  /** the fan stops helping once the ball already moves this fast along the blow direction */
  maxAssistSpeed?: number;
  pulse?: FanPulse;
}

export const FAN_DEFAULTS = {
  falloff: 'linear' as FanFalloff,
  maxAssistSpeed: 12,
} as const;

export function fanPulseActive(pulse: FanPulse | undefined, elapsed: number): boolean {
  if (!pulse) return true;
  const period = pulse.periodSeconds;
  if (!Number.isFinite(period) || period <= 0) return true;
  const duty = clamp(pulse.dutyCycle ?? 0.5, 0, 1);
  if (duty <= 0) return false;
  if (duty >= 1) return true;
  const phase = pulse.phase ?? 0;
  const position = (((elapsed + phase) % period) + period) % period;
  return position < period * duty;
}

export class Fan implements BallObstacle<FanConfig> {
  readonly id: string;
  readonly kind = 'fan' as const;
  enabled: boolean;
  private readonly direction: Vec3 | null;

  constructor(readonly config: FanConfig) {
    this.id = config.id;
    this.enabled = config.enabled ?? true;
    this.direction = normalizeVec3(config.direction);
  }

  /** Blow direction after normalization, or null when the configured direction is degenerate. */
  get blowDirection(): Vec3 | null {
    return this.direction;
  }

  isBlowing(elapsed: number): boolean {
    return this.enabled && this.direction !== null && fanPulseActive(this.config.pulse, elapsed);
  }

  reset(): void {}

  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
    const dt = Math.max(0, context.dt);
    const direction = this.direction;
    if (dt <= 0 || !direction || !this.isBlowing(context.elapsed)) return null;
    if (!zoneContains(this.config.zone, ball.position, ball.radius ?? 0)) return null;

    const falloff =
      (this.config.falloff ?? FAN_DEFAULTS.falloff) === 'linear' ? zoneFalloff(this.config.zone, ball.position) : 1;
    if (falloff <= 0) return null;

    const maxAssistSpeed = this.config.maxAssistSpeed ?? FAN_DEFAULTS.maxAssistSpeed;
    const headroom = maxAssistSpeed - dotVec3(ball.velocity, direction);
    if (headroom <= 0) return null;

    const push = Math.min(Math.max(0, this.config.strength) * falloff * dt, headroom);
    if (push <= 1e-6) return null;
    return { obstacleId: this.id, kind: this.kind, deltaVelocity: scaleVec3(direction, push) };
  }
}
